"""R15 report tables (markdown) from the goff_r15.py outputs under $SCRATCH/grl_review/R15/out. No statistic is computed here;
one orientation check of the Goff grid (a continental-interior node is missing, an open-ocean node is valid) is asserted."""
from __future__ import annotations
import json, math, os
import numpy as np, pandas as pd
OUT = "/scratch/users/scdobbs/grl_review/R15/out"
REP = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); TABLES = f"{REP}/tables"
GRID = f"{REP}/inputs/goff/abyssal_hill_rms_prediction_v2.0.grd"

def f(v, n=1):
    return "—" if v is None or (isinstance(v, float) and not math.isfinite(v)) else f"{v:,.{n}f}"
def w(name, L, src):
    os.makedirs(TABLES, exist_ok=True); open(f"{TABLES}/{name}", "w").write(f"<!-- generated by report_tables_r15.py from {src} (goff_r15.py) -->\n" + "\n".join(L) + "\n")

if __name__ == "__main__":
    import netCDF4
    d = netCDF4.Dataset(GRID); x = np.asarray(d["x"][:]); y = np.asarray(d["y"][:]); z = d["z"]
    node = lambda lon, lat: float(z[int(np.argmin(abs(y - lat))), int(np.argmin(abs(x - lon)))])
    orient = dict(kansas_m100_p40=node(-100, 40), s_pacific_m100_m40=node(-100, -40), sahara_p10_p20=node(10, 20), s_atlantic_m20_m20=node(-20, -20)); d.close()
    assert orient["kansas_m100_p40"] == -999 and orient["sahara_p10_p20"] == -999 and orient["s_pacific_m100_m40"] > 0 and orient["s_atlantic_m20_m20"] > 0, orient
    G = json.load(open(f"{OUT}/grid_facts.json")); g = G["goff"]; MH = json.load(open(f"{OUT}/must_hold.json")); S = json.load(open(f"{OUT}/stats.json"))
    T = pd.read_csv(f"{OUT}/units.csv"); REC = json.load(open(f"{OUT}/units_record.json"))
    # ---- grid facts (§1.1)
    L = ["| item | value |", "|---|---|",
         f"| file / sha256 | `{g['file']}` / `{g['sha256']}` |",
         f"| format | {g['data_model']} (netCDF-3), GMT {g['global_attrs']['GMT_version']}; Conventions {g['global_attrs']['Conventions']}; title attribute `{g['global_attrs']['title']}`; history `{g['global_attrs']['history']}` |",
         f"| node registration | {g['registration']} |",
         f"| node spacing | {g['node_spacing_deg'][0]:.6f}° = {g['node_spacing_arcmin'][0]:.3f} arcmin in x and y |",
         f"| extent (node coordinates) | x {g['x_first_last'][0]} to {g['x_first_last'][1]:.5f} ({g['dimensions']['x']} columns, full 360° without a duplicated seam); y {g['y_first_last'][0]} to {g['y_first_last'][1]:.5f} ({g['dimensions']['y']} rows) |",
         f"| CRS | {g['crs']} |", f"| variable / units | `z` (long_name 'z'), float32; {g['units']} |",
         f"| missing-value convention | **no NaN node** ({g['n_nan']} of {g['n_nodes']:,}); missing = **−999** ({g['n_sentinel_minus999']:,} nodes, {1 - g['frac_valid']:.3f}); `_FillValue` = NaN is declared but unused. R15 treats −999 as missing (NaN) |",
         f"| valid values | {g['n_valid']:,} nodes ({g['frac_valid']:.3f}); min {g['valid_min']:.2f}, p1 {g['valid_percentiles']['1']:.1f}, median {g['valid_percentiles']['50']:.1f}, p99 {g['valid_percentiles']['99']:.1f}, max {g['valid_max']:.1f} m; **{g['n_valid_negative']:,} negative values** (none in any unit neighbourhood) |",
         f"| additional layers | {'none' if not g['other_layers'] else g['other_layers']}: **no computed / interpolated flag** → classes from the §2.3 proxies |",
         f"| orientation check | node at (−100°, 40°) {orient['kansas_m100_p40']:.0f}, (10°, 20°) {orient['sahara_p10_p20']:.0f}; (−100°, −40°) {orient['s_pacific_m100_m40']:.1f}, (−20°, −20°) {orient['s_atlantic_m20_m20']:.1f} (continents missing, oceans valid) |"]
    a = G["age"]; k = G["kw"]
    L += ["", "| proxy | source URL | version | sha256 |", "|---|---|---|---|",
          f"| crustal age | {a['url']} | {a['version']}; {a['shape'][1]} × {a['shape'][0]} nodes, {a['spacing_deg']:.1f}° spacing, NaN off oceanic crust | `{a['sha256']}` |",
          f"| (its README) | https://www.earthbyte.org/webdav/ftp/earthbyte/agegrid/2020/Grids/README.txt | dated 29 September 2020 (updates to 30 June 2022) | `e872faa247d8f61ae5772d28145bd7ccac45ec60f600cf5fa1f7f915f631bb02` |",
          f"| seamount census | {k['url']} | {k['version']}; {k['n']:,} seamounts ({k['n_note']}); major axis {k['major_km_range'][0]}–{k['major_km_range'][1]} km; {k['radius_rule']} | `{k['sha256']}` |"]
    w("grid_facts.md", L, "grid_facts.json")
    # ---- must hold (§3) and its diagnostic
    dg = MH["diagnostic"]
    L = ["| statistic (16 units, median s_lr vs median A_fine) | Spearman ρ [95 % CI] | |CI − R08| | within 0.01 |", "|---|---|---|---|",
         f"| R08 §4 (seed 20261009, as reported) | +0.697 [+0.305, +0.866] | | |",
         f"| **R15, directive seed 20261014** | {MH['rho']:+.3f} [{MH['ci95'][0]:+.3f}, {MH['ci95'][1]:+.3f}] | {MH['abs_dev'][1]:.3f} / {MH['abs_dev'][2]:.3f} (ρ {MH['abs_dev'][0]:.3f}) | **no** |",
         f"| R15 recomputation with the R08 seed 20261009 (diagnostic) | {dg['with_r08_seed']['rho']:+.3f} [{dg['with_r08_seed']['ci95'][0]:+.3f}, {dg['with_r08_seed']['ci95'][1]:+.3f}] | {abs(dg['with_r08_seed']['ci95'][0] - 0.305):.3f} / {abs(dg['with_r08_seed']['ci95'][1] - 0.866):.3f} | yes |",
         f"| 100 seeds 20261000–20261099 (diagnostic) | lower bound {dg['ci_lo']['min']:+.3f} to {dg['ci_lo']['max']:+.3f} (median {dg['ci_lo']['median']:+.3f}); upper {dg['ci_hi']['min']:+.3f} to {dg['ci_hi']['max']:+.3f} (median {dg['ci_hi']['median']:+.3f}) | | {round(dg['frac_seeds_within_tol'] * 100)} of 100 |"]
    w("must_hold.md", L, "must_hold.json")
    # ---- unit table (§4.2; §3.4 ratio withheld while the must-hold HOLD stands)
    L = ["| unit | group | setting (manifest terrain_class) | centroid lon, lat | area (km²) | depth (m) | crustal age (Myr) | nearest K&W seamount: distance to footprint (km) / radius (km) | domain class (reason) | Goff (a) centroid bilinear (m) | Goff (b) median within 0.5° (m) [non-missing / nodes] | median A_fine (m) | median s_lr (m) | interior D1 A_fine / s_lr (m) | fine band (m) |",
         "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in T.itertuples():
        name = "lu16 (EW0207, separate)" if r.unit == "lu16" else r.unit
        cls = r.domain_class + (f" ({r.class_reason})" if isinstance(r.class_reason, str) and r.class_reason else "")
        if r.domain_class_sensitivity != r.domain_class: cls += f"; with radius = major axis: {r.domain_class_sensitivity}"
        intr = f"{f(r.A_fine_int_median_m, 4)} / {f(r.s_lr_int_median_m, 2)}" if r.n_int_tiles else "no interior tile"
        age = f(r.crustal_age_myr, 2) if r.oceanic_crust else "NaN (off oceanic crust)"
        L.append(f"| {name} | {r.group} | {r.setting} | {r.centroid_lon:.3f}, {r.centroid_lat:.3f} | {r.area_km2:.1f} | {r.depth_m:,.0f} | {age} | {(f'{r.smt_nearest_id}: {r.smt_nearest_dist_km:.1f} / {r.smt_nearest_radius_km:.2f}' if isinstance(r.smt_nearest_id, str) else 'none within 6°')} | {cls} | {f(r.goff_a)} | {f(r.goff_b)} [{r.goff_b_n_valid} / {r.goff_b_n_nodes}] | {r.A_fine_median_m:.4f} | {r.s_lr_median_m:.2f} | {intr} | {r.lam_short_m:.1f}–{r.lam_long_m:.1f} |")
    w("units.md", L, "units.csv")
    # ---- set sizes (§3.1)
    D = T[T.unit != "lu16"]; ss = S["set_sizes"]
    sens_p = int((D.domain_class_sensitivity == "computed").sum())
    L = ["| set | units | n |", "|---|---|---|",
         f"| primary (computed) | {', '.join(D[D.domain_class == 'computed'].unit)} | {ss['primary_n']} |",
         f"| secondary (computed + possibly interpolated) | {', '.join(D[D.domain_class.isin(['computed', 'possibly interpolated'])].unit)} | {ss['secondary_n']} |",
         f"| no value | {', '.join(D[D.domain_class == 'no value'].unit)} | {int((D.domain_class == 'no value').sum())} |",
         f"| primary with radius = major axis (sensitivity) | {', '.join(D[D.domain_class_sensitivity == 'computed'].unit)} | {sens_p} |",
         "| of the ten real-relief units with interior tiles, in primary / secondary | " + f"{', '.join(u for u in D[D.domain_class == 'computed'].unit if u in ('lu00','lu04','lu05','lu07','lu08','lu09','lu13','lu15','nu00'))} / {', '.join(u for u in D[D.domain_class.isin(['computed','possibly interpolated'])].unit if u in ('lu00','lu04','lu05','lu07','lu08','lu09','lu13','lu15','nu00'))} | "
         f"{sum(u in ('lu00','lu04','lu05','lu07','lu08','lu09','lu13','lu15','nu00') for u in D[D.domain_class == 'computed'].unit)} / {sum(u in ('lu00','lu04','lu05','lu07','lu08','lu09','lu13','lu15','nu00') for u in D[D.domain_class.isin(['computed','possibly interpolated'])].unit)} |"]
    w("sets.md", L, "stats.json, units.csv")
    # ---- multi-pair units: pair-level spread (evidence for HOLD H2)
    L = ["| unit | pair | pair centroid lon, lat | distance to unit centroid (km) | Goff (b) at pair centroid (m) [non-missing] | pair median ship elevation (m) |", "|---|---|---|---|---|---|"]
    for u in ("lu05", "lu07", "lu13", "lu15"):
        loc = REC[u]["location"]
        for p, v in REC[u]["per_pair_goff"].items():
            dd = math.degrees(math.acos(min(1, math.sin(math.radians(v['centroid_lat'])) * math.sin(math.radians(loc['lat'])) + math.cos(math.radians(v['centroid_lat'])) * math.cos(math.radians(loc['lat'])) * math.cos(math.radians(v['centroid_lon'] - loc['lon']))))) * 111.195
            L.append(f"| {u} | {p} | {v['centroid_lon']:.3f}, {v['centroid_lat']:.3f} | {dd:.1f} | {f(v['goff_b'])} [{v['n_valid']}] | {REC[u]['depth']['per_pair'][p]['median_elev_m']:,.0f} |")
    w("multi_pair_units.md", L, "units_record.json")
    # ================= §8: the run under Steve's rulings of 2026-10-13 (out_ruling/)
    OR = OUT + "_ruling"
    if os.path.exists(f"{OR}/stats.json"):
        MR = json.load(open(f"{OR}/must_hold.json")); SR = json.load(open(f"{OR}/stats.json")); TR = pd.read_csv(f"{OR}/units.csv"); PR = pd.read_csv(f"{OR}/pairs.csv")
        r8, n14 = MR["r08"], MR["seed_20261014_row"]
        L = ["| statistic (16 units, median s_lr vs median A_fine) | Spearman ρ [95 % CI] | |difference| |", "|---|---|---|",
             f"| R08 §4, OAK `level_correlations.json` | {r8['rho']:+.6f} [{r8['ci95'][0]:+.6f}, {r8['ci95'][1]:+.6f}] | |",
             f"| **R15 must-hold, seed 20261009 (ruling H1 a)** | {MR['rho']:+.6f} [{MR['ci95'][0]:+.6f}, {MR['ci95'][1]:+.6f}] | {max(MR['abs_dev']):.1e}: **exact** |",
             f"| same statistic, seed 20261014 (reported) | {n14['rho']:+.3f} [{n14['ci95'][0]:+.3f}, {n14['ci95'][1]:+.3f}] | |"]
        w("r_must_hold.md", L, "out_ruling/must_hold.json")
        def cell(st, q):
            return f"{st[q]['rho']:+.3f} [{st[q]['ci95'][0]:+.3f}, {st[q]['ci95'][1]:+.3f}]" if q in st else "—"
        L = ["| set | n | units | Goff vs fine relief | Goff vs s_lr | s_lr vs fine relief (same units) | partial ρ Goff, fine \\| s_lr |", "|---|---|---|---|---|---|---|"]
        for k, lab in (("primary", "primary: computed"), ("secondary", "secondary: computed + possibly interpolated"), ("primary_ten_interior", "§3.3 primary ∩ ten, interior D1 medians"), ("secondary_ten_interior", "§3.3 secondary ∩ ten, interior D1 medians")):
            st = SR[k]; note = " (fewer than 5: table only)" if st["n"] < 5 else ""
            L.append(f"| {lab} | {st['n']}{note} | {', '.join(st['units'])} | {cell(st, 'goff_vs_fine')} | {cell(st, 'goff_vs_s_lr')} | {cell(st, 's_lr_vs_fine')} | {cell(st, 'partial_goff_fine_given_s_lr') if not k.endswith('interior') else 'not requested'} |")
        sc = SR["sensitivity_classes"]
        L.append(f"| primary with radius = major axis (H3 sensitivity) | {sc['primary_n']} (table only) | {', '.join(sc['primary_units'])} | — | — | — | — |")
        w("r_correlations.md", L, "out_ruling/stats.json")
        L = ["| unit | group | domain class (reason; per pair where the unit has more than one) | pairs with a value / pairs | crustal age (Myr) per pair | nearest K&W seamount over pairs: distance (km) / radius (km) | Goff (a) (m) | Goff (b) (m) | median A_fine (m) | ratio Goff (b) / A_fine | median s_lr (m) | interior D1 A_fine / s_lr (m) | fine band (m) |",
             "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
        for r in TR.itertuples():
            name = "lu16 (EW0207, separate)" if r.unit == "lu16" else r.unit
            cls = r.domain_class + (f" ({r.class_reason.replace(' | ', '; ')})" if isinstance(r.class_reason, str) and r.class_reason else "")
            if r.domain_class_sensitivity != r.domain_class: cls += f"; with radius = major axis: {r.domain_class_sensitivity}"
            ages = [float(a) for a in str(r.crustal_age_pairs).split(";")]
            age = "; ".join("NaN" if not math.isfinite(a) else f"{a:.2f}" for a in ages) if len(ages) <= 3 else (f"all {len(ages)} NaN (off oceanic crust)" if not any(map(math.isfinite, ages)) else f"{min(a for a in ages if math.isfinite(a)):.2f}–{max(a for a in ages if math.isfinite(a)):.2f}")
            smt = f"{r.smt_nearest_id}: {r.smt_nearest_dist_km:.1f} / {r.smt_nearest_radius_km:.2f}" if isinstance(r.smt_nearest_id, str) else "none within 6°"
            intr = f"{f(r.A_fine_int_median_m, 4)} / {f(r.s_lr_int_median_m, 2)}" if r.n_int_tiles else "no interior tile"
            L.append(f"| {name} | {r.group} | {cls} | {r.n_pairs_with_value} / {r.n_pairs} | {age} | {smt} | {f(r.goff_a)} | {f(r.goff_b)} | {r.A_fine_median_m:.4f} | {f(r.ratio_goff_over_fine, 0)} | {r.s_lr_median_m:.2f} | {intr} | {r.lam_short_m:.1f}–{r.lam_long_m:.1f} |")
        w("r_units.md", L, "out_ruling/units.csv")
        L = ["| unit | pair | centroid lon, lat | crustal age (Myr) | nearest seamount (km / radius km) | Goff (b) (m) [non-missing / 225] | class (reason) |", "|---|---|---|---|---|---|---|"]
        for r in PR[PR.unit.isin(TR[TR.n_pairs > 1].unit)].itertuples():
            smt = f"{r.smt_nearest_id}: {r.smt_nearest_dist_km:.1f} / {r.smt_nearest_radius_km:.2f}" if isinstance(r.smt_nearest_id, str) else "none"
            L.append(f"| {r.unit} | {r.pair} | {r.centroid_lon:.3f}, {r.centroid_lat:.3f} | {f(r.crustal_age_myr, 2)} | {smt} | {f(r.goff_b)} [{r.goff_b_n_valid}] | {r.domain_class}{f' ({r.class_reason})' if isinstance(r.class_reason, str) and r.class_reason else ''} |")
        w("r_pairs_multi.md", L, "out_ruling/pairs.csv")
    print("tables written:", sorted(os.listdir(TABLES)))
